"""Build a lightweight pricing page and persistent portfolio navigation links."""
from pathlib import Path
from html import escape as esc
import json
from urllib.parse import urlencode
from bs4 import BeautifulSoup

ROOT = Path(__file__).resolve().parents[1]
DIST = ROOT / 'dist'
data = json.loads((ROOT / 'content/pricing.json').read_text(encoding='utf8'))

def money(value):
    return f'<span data-price="{value}">TSh {value:,}</span>'

def enquiry(name, price, period='one-time'):
    query = urlencode({'subject':name+' package enquiry','body':f'Hi Isack, I am interested in {name}, starting at TSh {price:,} ({period}).\n\nProject idea:\nTimeline:\nBudget range:\n'})
    return f'<a class="chrome-button package-contact" href="mailto:lugata619@gmail.com?{esc(query,quote=True)}" data-package="{esc(name)}" data-package-price="{price}" data-package-period="{period}">Discuss {esc(name.lower())} <span aria-hidden="true">↗</span></a>'

cards = []
for i, p in enumerate(data['packages']):
    cards.append(f'''<article class="price-package" id="{p['id']}"><div class="package-top"><span class="package-number">0{i+1}</span><span>{p['name']}</span>{'<span class="package-label">For growing businesses</span>' if p['id']=='business' else ''}</div><h2>{p['headline']}</h2><p class="package-audience">{p['audience']}</p><div class="package-price"><span>Starting at</span><strong>{money(p['price'])}</strong><span>One-time build · {p['delivery']}</span></div>{enquiry(p['name'], p['price'])}<ul>{''.join('<li>'+esc(item)+'</li>' for item in p['features'])}</ul><p class="package-boundary">{p['boundary']}</p></article>''')

def rows(items):
    return ''.join(f'<article class="service-price-row"><div><h3>{esc(p["name"])}</h3><p>{esc(p["description"])}</p></div><div class="service-price"><span>From</span><strong>{money(p["price"])}</strong><span>{"per " + p["period"] if p["period"] != "one-time" else "one-time"}</span>{enquiry(p["name"],p["price"],p["period"])}</div></article>' for p in items)

page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Website Pricing | Isack Lugata</title><link rel="stylesheet" href="/assets/personal/case-fonts.css"><link rel="stylesheet" href="/assets/personal/pricing.css"><link rel="stylesheet" href="/assets/personal/contact.css"><script defer src="/assets/personal/contact.js"></script><script defer src="/assets/personal/pricing.js"></script></head><body class="pricing-page"><a class="pricing-skip" href="#packages">Skip to packages</a><header class="pricing-header"><a class="pricing-name" href="/">Isack Lugata</a><nav aria-label="Main navigation"><a href="/">Works</a><a href="/about">Story</a><a href="/pricing" aria-current="page">Pricing</a><a href="/blog/">Journal</a></nav><a class="chrome-button pricing-chat" href="mailto:lugata619@gmail.com">Let’s chat</a></header><main class="pricing-shell"><section class="pricing-intro"><div><span class="pricing-eyebrow">Independent developer · Dar es Salaam, working worldwide</span><h1>A proper home<br>for your <em>next big thing.</em></h1><p>A sharp landing page. A store that takes orders. A system that makes the everyday easier. Choose your starting point; I’ll help you build what comes next.</p><a class="text-link" href="/#projects">See the work behind the prices ↗</a></div><aside class="pricing-note"><span>Made for your next chapter</span><ul><li>Thoughtful design</li><li>Frontend + backend</li><li>Ready for mobile</li><li>Help after launch</li></ul><span class="note-signature">Let's make it happen.</span></aside></section><section class="pricing-selection" id="packages"><div><span class="pricing-eyebrow">Clear scope. A sensible starting point.</span><h2>Choose what you’re building.</h2></div><fieldset class="currency-picker"><legend>Display currency</legend><button type="button" data-currency="TZS" aria-pressed="true">TSh</button><button type="button" data-currency="USD" aria-pressed="false">USD $</button><button type="button" data-currency="EUR" aria-pressed="false">EUR €</button></fieldset></section><p class="currency-note" id="currency-note" aria-live="polite">Prices are in Tanzanian shillings. USD and EUR are approximate display conversions.</p><div class="package-grid">{''.join(cards)}</div><p class="pricing-terms">Starting prices are for the scopes above. Timelines begin after content and access are ready. Your written quote confirms the final scope, payment milestones, applicable taxes, and any third-party costs. Domain, hosting, paid tools, and maintenance are separate unless expressly included. Bug-fix support covers the agreed build, not new features.</p><section class="pricing-section"><div class="section-lead"><span class="pricing-eyebrow">The details that make a difference</span><h2>More than a nice-looking website.</h2><p>Every build includes responsive layouts, optimized images, descriptive page metadata, and a clear route to contact or purchase. Add deeper content, search, or integrations when your business needs them.</p></div>{rows(data['extras'])}<p class="pricing-terms">Search setup helps search engines and AI systems understand accessible, well-structured content. Rankings, traffic, and AI citations cannot be guaranteed. Ongoing SEO work and advertising budgets are separate.</p></section><section class="pricing-section" id="care"><div class="section-lead"><span class="pricing-eyebrow">After launch</span><h2>Keep it fast.<br>Keep it looked after.</h2><p>Hosting keeps the site online. Care keeps its software and content maintained. Choose either or both; you can also use your own hosting.</p></div>{rows(data['care'])}<p class="pricing-terms">Support is during business hours, East Africa Time. These are not 24/7 emergency plans. Traffic limits, backup recovery, renewals, and any additional resource costs are confirmed before you sign up.</p></section><section class="pricing-questions"><h2>A few things you might be wondering.</h2><div><article><h3>Can you build a mobile app or AI tool?</h3><p>Yes. Mobile apps, document assistants, and custom AI integrations are scoped individually. Tell me the main task your users need to complete, and we can define a practical first version.</p></article><article><h3>What if I already have a website?</h3><p>I can help with a redesign, speed improvements, backend work, or integrations. We’ll review what is worth keeping before pricing the changes.</p></article><article><h3>Will I own the website?</h3><p>Your custom project code and content are handed over after final payment. Third-party software, assets, and services remain subject to their own licences.</p></article><article><h3>Do I need to know which package fits?</h3><p>No. A short description of your business and what the website should do is enough to start the conversation.</p></article></div></section><footer class="pricing-footer"><span class="pricing-eyebrow">Your idea, with someone who can build it.</span><h2>Ready for the<br>next adventure?</h2><a class="chrome-button" href="mailto:lugata619@gmail.com">Let’s talk about your project ↗</a><nav aria-label="Footer"><a href="/">Works</a><a href="/about">Story</a><a href="/blog/">Journal</a><a href="/blog/privacy/">Privacy</a><a href="/blog/terms/">Terms</a></nav><p>Dar es Salaam, Tanzania · Frontend, mobile, backend & applied AI.</p></footer></main></body></html>'''
(DIST / 'pricing.html').write_text(page, encoding='utf8')
for name in ['pricing.css','site-links.css','site-links.js']:
    (DIST / 'assets/personal' / name).write_text((ROOT/'scripts'/name).read_text(encoding='utf8'),encoding='utf8')
script = (ROOT/'scripts/pricing.js').read_text(encoding='utf8').replace('__EXCHANGE__',json.dumps(data['exchange']))
(DIST/'assets/personal/pricing.js').write_text(script,encoding='utf8')
for path in DIST.glob('*.html'):
    if path.stem == 'pricing': continue
    soup = BeautifulSoup(path.read_text(encoding='utf8'),'html.parser')
    for old in soup.select('.portfolio-extra-nav, [data-site-links]'): old.decompose()
    nav = BeautifulSoup('<nav class="portfolio-extra-nav" aria-label="Explore more"><a href="/pricing">Pricing</a><a href="/blog/">Journal</a></nav>','html.parser')
    soup.body.append(nav)
    soup.head.append(soup.new_tag('link', rel='stylesheet', href='/assets/personal/site-links.css', attrs={'data-site-links':'true'}))
    soup.head.append(soup.new_tag('script', src='/assets/personal/site-links.js', defer='', attrs={'data-site-links':'true'}))
    path.write_text(str(soup),encoding='utf8')
print('Built pricing packages, currency display, and portfolio Pricing / Journal navigation.')
